public class CustomerActivity extends Activity {
    private NativeUi ui;
    private CustomerStore store;
    private final ImageTools images=new ImageTools();
    private final Map<String,EditText> fields=new HashMap<>();
    private final NumberFormat currency=NumberFormat.getCurrencyInstance(new Locale("es","PE"));
    private LinearLayout root,content,footer;
    private LinearLayout summary;
    private ScrollView scroll;
    private String screen="food",category="Todo",selectedId="";
    private int step=0;
    private JSONObject details;
    private JSONObject viewState,bundledSale;
    private DeliveryLocator locator;
    private boolean locating=false,refreshLocationUi=false;

    @Override public void onCreate(Bundle state){
        super.onCreate(state);ui=new NativeUi(this);store=new CustomerStore(this);details=store.snapshot().optJSONObject("details");locator=new DeliveryLocator(this);try{bundledSale=store.bundledSale(this);}catch(Exception ignored){}try{details=DeliveryDestination.normalized(details);}catch(JSONException error){throw new IllegalStateException(error);}
        if(state!=null){screen=state.getString("screen","food");category=state.getString("category","Todo");selectedId=state.getString("id","");step=state.getInt("step",0);}
        getWindow().getDecorView().setSystemUiVisibility(0);getWindow().setStatusBarColor(NativeUi.DEEP);getWindow().setNavigationBarColor(NativeUi.WINE);render();
    }
    @Override public void onPause(){captureDetails();if(locator!=null)locator.cancel();refreshLocationUi=locating;locating=false;super.onPause();}
    @Override public void onResume(){super.onResume();if(refreshLocationUi&&root!=null){refreshLocationUi=false;render();}}
    @Override public void onSaveInstanceState(Bundle out){captureDetails();super.onSaveInstanceState(out);out.putString("screen",screen);out.putString("category",category);out.putString("id",selectedId);out.putInt("step",step);}
    @Override public void onDestroy(){images.clear();super.onDestroy();}
    @Override public void onBackPressed(){if(screen.equals("checkout")&&step>0){captureDetails();step--;render();}else if(screen.equals("food"))super.onBackPressed();else go(screen.equals("receipt")?"orders":screen.equals("checkout")?"cart":"food","");}
    private int dp(float n){return ui.dp(n);}
    private JSONObject state(){return viewState==null?store.snapshot():viewState;}
    private JSONObject catalog(){return state().optJSONObject("catalog");}
    private JSONObject settings(){return catalog().optJSONObject("settings");}
    private String cash(double n){return currency.format(n);}
    private void put(JSONObject object,String name,Object value){try{object.put(name,value);}catch(JSONException error){throw new IllegalStateException(error);}}
    private JSONObject product(String id){JSONArray products=catalog().optJSONArray("products");for(int i=0;i<products.length();i++)if(products.optJSONObject(i).optString("id").equals(id))return products.optJSONObject(i);return null;}
    private String unit(JSONObject p){return SaleRules.unit(p.optString("saleUnit",SaleRules.defaultUnit(p.optString("category"))));}
    private String payment(){switch(details.optString("payment","cash")){case "yape":return "Yape";case "plin":return "Plin";default:return "Efectivo";}}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private void go(String next,String id){captureDetails();if(locator!=null)locator.cancel();locating=false;if(root!=null)((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);screen=next;selectedId=id;render();}
    private void add(LinearLayout parent,View child,int gap){ui.add(parent,child,gap);}
    private void title(String title,String subtitle){add(content,ui.heading(title,26),0);if(!subtitle.isEmpty())add(content,ui.text(subtitle,14,NativeUi.MUTED,false),5);}
    private void note(String text){add(content,ui.text(text,14,NativeUi.MUTED,false),12);}
    private void primary(String text,Runnable action){footer.setVisibility(View.VISIBLE);footer.removeAllViews();footer.addView(ui.button(text,true,null,action),new LinearLayout.LayoutParams(-1,-2));}
    private String activeTab(){if(screen.equals("detail"))return "food";if(screen.equals("checkout"))return "cart";if(screen.equals("receipt"))return "orders";return screen;}
    private boolean rootScreen(){return Arrays.asList("food","offers","cart","orders").contains(screen);}
    private void render(){
        viewState=store.snapshot();fields.clear();root=ui.column();root.setBackgroundColor(NativeUi.BG);setContentView(root);
        String heading=rootScreen()?"ManchApp":screen.equals("detail")?"Tu antojo":screen.equals("checkout")?"Arma tu pedido":"Tu pedido";
        root.addView(ui.toolbar(heading,rootScreen()?"PEDIDOS · MANCHAY":"",rootScreen()?null:()->onBackPressed(),null));
        scroll=new ScrollView(this);scroll.setFillViewport(true);content=ui.column();content.setPadding(dp(16),dp(16),dp(16),dp(22));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        footer=ui.column();footer.setPadding(dp(16),dp(8),dp(16),dp(9));footer.setVisibility(View.GONE);root.addView(footer);
        switch(screen){case "food":showFood();break;case "offers":showOffers();break;case "cart":showCart();break;case "detail":showProduct();break;case "checkout":showCheckout();break;case "orders":showOrders();break;case "receipt":showReceipt();break;default:screen="food";showFood();}
        int count=store.count();root.addView(ui.navigation(new String[]{"food","offers","cart","orders"},new String[]{"Comida","Ofertas",count>0?"Carrito · "+count:"Carrito","Pedidos"},new String[]{"food","tag","cart","orders"},activeTab(),id->go(id,"")));
    }
    private ImageView image(JSONObject product,int edge){ImageView view=new ImageView(this);view.setScaleType(ImageView.ScaleType.CENTER_CROP);view.setBackground(ui.background(0xffeabe83,0,15));view.setClipToOutline(true);Bitmap bitmap=images.productThumbnail(this,product,dp(edge));if(bitmap!=null)view.setImageBitmap(bitmap);else view.setImageDrawable(new DishArt(product.optString("illustration","papa")));view.setContentDescription((bitmap==null?"Ilustración referencial de ":"Foto de ")+product.optString("name"));return view;}
    private boolean accepting(){return SaleSchedule.unavailable(settings(),System.currentTimeMillis()).isEmpty();}
    private void saleCard(){String closed=SaleSchedule.unavailable(settings(),System.currentTimeMillis());LinearLayout sale=ui.message("PRÓXIMA VENTA",SaleSchedule.day(settings()),NativeUi.GOLD);add(sale,ui.text("Reserva con anticipación para esta jornada.",14,NativeUi.INK,true),9);add(sale,ui.text(closed.isEmpty()?"Reservas hasta "+SaleSchedule.deadline(settings()):closed,14,NativeUi.WINE,true),9);if(!closed.isEmpty()&&bundledSale!=null&&bundledSale.optString("saleDate").compareTo(settings().optString("saleDate"))>0)add(sale,ui.button("Ver catálogo actualizado",false,null,()->new AlertDialog.Builder(this).setTitle("Catálogo incluido en esta versión").setMessage("Venta: "+SaleSchedule.day(bundledSale)+"\nSe cargará el catálogo guardado en esta actualización de la app; todavía no está sincronizado con la olla.\nTus pedidos anteriores se conservarán. Si tienes un carrito de otra fecha, tendrás que revisarlo.").setNegativeButton("Volver",null).setPositiveButton("Cargar catálogo",(d,w)->{captureDetails();try{store.loadBundledCatalog(this);go("food","");}catch(Exception error){toast("No pudimos cargar el catálogo. Tus datos se conservan.");}}).show()),12);add(content,sale,13);}
    private void showFood(){
        add(content,ui.heading("Reserva tu antojo",27),12);add(content,ui.text("Olla Común "+settings().optString("name"),14,NativeUi.MUTED,true),3);saleCard();
        HorizontalScrollView horizontal=new HorizontalScrollView(this);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout filters=new LinearLayout(this);
        for(String label:new String[]{"Todo","Salados","Antojitos","Postres","Bebidas","Combos"}){boolean selected=category.equals(label);TextView chip=ui.text(label,14,selected?NativeUi.CARD:NativeUi.WINE,true);chip.setPadding(dp(17),dp(12),dp(17),dp(12));chip.setMinHeight(dp(48));chip.setGravity(Gravity.CENTER);chip.setSelected(selected);chip.setBackground(ui.background(selected?NativeUi.WINE:NativeUi.CARD,selected?0:NativeUi.LINE,24));ui.buttonRole(chip);chip.setOnClickListener(v->{category=label;render();});LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-2,-2);params.rightMargin=dp(8);filters.addView(chip,params);}horizontal.addView(filters);add(content,horizontal,14);
        JSONArray products=catalog().optJSONArray("products");int count=0;
        for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(!p.optString("line").equals("commercial")||(!category.equals("Todo")&&!p.optString("category").equals(category)))continue;productCard(p);count++;}
        if(count==0)empty("Aquí aparecerán los antojitos","Prueba otra categoría para ver el resto de la comida.");
        note("Productos del emprendimiento para recaudar fondos y apoyar a la olla.");
    }
    private void productCard(JSONObject p){
        LinearLayout card=ui.card();card.setPadding(dp(12),dp(12),dp(12),dp(12));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(image(p,112),new LinearLayout.LayoutParams(dp(112),dp(112)));
        LinearLayout copy=ui.column();copy.setPadding(dp(12),0,0,0);add(copy,ui.text(p.optString("category").toUpperCase(new Locale("es")),10,NativeUi.CORAL,true),0);add(copy,ui.heading(p.optString("name"),19),4);String portion=p.optString("portion");if(!portion.isEmpty())add(copy,ui.text(portion,13,NativeUi.INK,false),4);add(copy,ui.text("Para el "+SaleSchedule.day(settings()),12,NativeUi.MUTED,false),6);if(!ImageTools.hasProductPhoto(p))add(copy,ui.text("Imagen referencial",10,NativeUi.MUTED,false),5);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));card.addView(row);
        LinearLayout bottom=new LinearLayout(this);bottom.setGravity(Gravity.CENTER_VERTICAL);LinearLayout price=ui.column();price.addView(ui.text(cash(p.optDouble("price")),23,NativeUi.WINE,true));price.addView(ui.text(unit(p),12,NativeUi.MUTED,false));bottom.addView(price,new LinearLayout.LayoutParams(0,-2,1));boolean available=p.optBoolean("available")&&p.optInt("stock")>0;int quantity=state().optJSONObject("cart").optInt(p.optString("id"));TextView action=ui.button(!accepting()?"Cerrado":available?(quantity>0?"Agregar · "+quantity:"Reservar"):"Sin cupos",true,null,()->changeQuantity(p,1,false));action.setTextSize(14);action.setEnabled(accepting()&&available&&quantity<p.optInt("stock"));action.setAlpha(action.isEnabled()?1f:.55f);bottom.addView(action,new LinearLayout.LayoutParams(dp(112),-2));add(card,bottom,10);card.setOnClickListener(v->go("detail",p.optString("id")));ui.buttonRole(card);add(content,card,13);
    }
    private void changeQuantity(JSONObject p,int delta,boolean wholeScreen){try{int quantity=state().optJSONObject("cart").optInt(p.optString("id"));store.quantity(p.optString("id"),quantity+delta);int y=scroll.getScrollY();render();scroll.post(()->scroll.scrollTo(0,y));if(!wholeScreen)toast("Agregado: "+p.optString("name"));}catch(Exception error){toast(error.getMessage());}}
    private void showProduct(){JSONObject p=product(selectedId);if(p==null||!p.optString("line").equals("commercial")){go("food","");return;}ImageView photo=image(p,320);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);add(content,photo,0);photo.getLayoutParams().height=dp(215);if(!ImageTools.hasProductPhoto(p))note("Ilustración referencial. ");add(content,ui.heading(p.optString("name"),28),16);add(content,ui.text(cash(p.optDouble("price"))+" "+unit(p),23,NativeUi.WINE,true),6);if(!p.optString("portion").isEmpty())add(content,ui.text(p.optString("portion"),17,NativeUi.INK,true),13);note(p.optString("description"));saleCard();add(content,ui.message("Recojo en la olla",SaleSchedule.window(settings()),NativeUi.CARD),15);note("Puedes elegir Olla Común Mujeres Emprendedoras o reparto por sector al continuar.");if(accepting()&&p.optBoolean("available")&&p.optInt("stock")>0)primary("Reservar en el carrito",()->{changeQuantity(p,1,true);});else note("Este producto no está disponible por ahora.");}
    private void showOffers(){title("Para compartir","Combos para la próxima venta de la olla.");saleCard();JSONArray promos=catalog().optJSONArray("promos");for(int i=0;promos!=null&&i<promos.length();i++){JSONObject promo=promos.optJSONObject(i);if(!promo.optBoolean("active"))continue;JSONObject p=product(promo.optString("productId"));if(p==null||!p.optString("line").equals("commercial"))continue;add(content,ui.message(promo.optString("title"),promo.optString("description"),NativeUi.GOLD),16);productCard(p);}double from=settings().optDouble("deliveryFreeFrom",0);if(from>0)add(content,ui.message("Reparto gratis desde "+cash(from),"Solo en sectores habilitados. Revisa el punto de encuentro antes de guardar tu reserva.",NativeUi.SOFT),16);note("Cada oferta corresponde a esta fecha de venta y tiene cupos limitados.");}
    private void empty(String title,String detail){add(content,ui.message(title,detail,NativeUi.GOLD),18);}
    private void showCart(){title("Tu carrito","Reservas para una misma jornada de venta.");saleCard();if(store.cartNeedsReview())note("Tu carrito corresponde a otra jornada. Vacíalo y vuelve a elegir los productos para esta fecha; tus pedidos anteriores se conservan.");if(store.count()==0){empty("Tu primer antojo te espera","Elige productos para la próxima venta o agrega un combo.");add(content,ui.button("Ver la comida",true,"food",()->go("food","")),18);return;}JSONObject cart=state().optJSONObject("cart");java.util.Iterator<String> ids=cart.keys();while(ids.hasNext()){JSONObject p=product(ids.next());if(p==null)continue;int quantity=cart.optInt(p.optString("id"));LinearLayout c=ui.card();add(c,ui.text(p.optString("name"),19,NativeUi.INK,true),0);add(c,ui.text(cash(p.optDouble("price"))+" "+unit(p),14,NativeUi.MUTED,false),5);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView minus=ui.button("−",false,null,()->changeQuantity(p,-1,true));minus.setContentDescription("Quitar uno de "+p.optString("name"));row.addView(minus,new LinearLayout.LayoutParams(dp(54),dp(50)));TextView amount=ui.text(String.valueOf(quantity),21,NativeUi.INK,true);amount.setGravity(Gravity.CENTER);row.addView(amount,new LinearLayout.LayoutParams(dp(44),-2));TextView plus=ui.button("+",false,null,()->changeQuantity(p,1,true));plus.setContentDescription("Agregar uno de "+p.optString("name"));plus.setEnabled(accepting()&&!store.cartNeedsReview()&&quantity<p.optInt("stock"));row.addView(plus,new LinearLayout.LayoutParams(dp(54),dp(50)));TextView price=ui.text(cash(quantity*p.optDouble("price")),19,NativeUi.WINE,true);price.setGravity(Gravity.RIGHT);row.addView(price,new LinearLayout.LayoutParams(0,-2,1));add(c,row,12);add(content,c,13);}add(content,ui.message("Comida: "+cash(store.subtotal()),"El reparto se calcula al elegir el sector. El recojo no tiene costo.",NativeUi.GOLD),16);add(content,ui.button("Vaciar carrito",false,null,()->{try{store.clearCart();render();}catch(Exception error){toast("No pudimos vaciar el carrito. Intenta otra vez.");}}),12);if(accepting()&&!store.cartNeedsReview())primary("Elegir cómo lo recibo",()->{step=0;go("checkout","");});}

    private EditText field(String key,String label,String hint,boolean phone){
        TextView name=ui.text(label,15,NativeUi.INK,true);add(content,name,16);EditText input=new EditText(this);input.setId(View.generateViewId());name.setLabelFor(input.getId());input.setTextSize(17);input.setTypeface(ui.regular);input.setTextColor(NativeUi.INK);input.setHintTextColor(NativeUi.MUTED);input.setHint(hint);input.setPadding(dp(14),dp(13),dp(14),dp(13));input.setMinHeight(dp(54));input.setBackground(ui.background(NativeUi.CARD,NativeUi.LINE,14));input.setInputType(phone?InputType.TYPE_CLASS_PHONE:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);if(phone)input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(9)});if(Arrays.asList("address","reference","meeting").contains(key)){input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(240)});input.setMinLines(key.equals("address")?1:2);input.setMaxLines(4);input.setGravity(Gravity.TOP);}input.setText(details.optString(key));fields.put(key,input);add(content,input,6);return input;
    }
    private void captureDetails(){if(details==null||store==null)return;for(Map.Entry<String,EditText> field:fields.entrySet())put(details,field.getKey(),field.getValue().getText().toString().trim());try{store.details(details);}catch(Exception error){toast("No pudimos conservar tus datos. Intenta otra vez antes de salir.");}}
    private void error(String field,String message){EditText input=fields.get(field);if(input!=null){input.setError(message);input.requestFocus();input.announceForAccessibility(message);}else toast(message);}
    private void choices(String[] keys,String[] labels,String selected,java.util.function.Consumer<String> action){LinearLayout row=new LinearLayout(this);for(int i=0;i<keys.length;i++){String key=keys[i];boolean active=key.equals(selected);TextView choice=ui.button(labels[i],false,null,()->action.accept(key));choice.setTextSize(14);choice.setSelected(active);choice.setTextColor(active?NativeUi.CARD:NativeUi.WINE);choice.setBackground(ui.background(active?NativeUi.WINE:NativeUi.CARD,active?0:NativeUi.LINE,14));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.setMargins(dp(i==0?0:4),0,dp(i==keys.length-1?0:4),0);row.addView(choice,params);}add(content,row,12);}
    private void showCheckout(){
        if(store.count()==0){empty("Tu carrito está vacío","Agrega algo de la comida antes de continuar.");primary("Elegir comida",()->go("food",""));return;}
        if(!accepting()){saleCard();primary("Volver al carrito",()->go("cart",""));return;}String[] names={"Cómo recibirlo","Tus datos","Revisar"};add(content,ui.heading(names[step],24),0);add(content,ui.text("Venta: "+SaleSchedule.day(settings()),13,NativeUi.WINE,true),6);LinearLayout steps=new LinearLayout(this);for(int i=0;i<3;i++){TextView label=ui.text((i+1)+". "+new String[]{"Entrega","Datos","Revisar"}[i],12,i==step?NativeUi.CARD:NativeUi.WINE,true);label.setPadding(dp(8),dp(9),dp(8),dp(9));label.setGravity(Gravity.CENTER);label.setBackground(ui.background(i==step?NativeUi.WINE:NativeUi.CARD,0,10));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.rightMargin=dp(5);steps.addView(label,params);}add(content,steps,12);
        if(step==0){
            choices(new String[]{"pickup","delivery"},new String[]{"En la olla","Con delivery"},details.optString("fulfillment","pickup"),key->{captureDetails();put(details,"fulfillment",key);render();});
            if(details.optString("fulfillment","pickup").equals("pickup")){add(content,ui.message("En la olla",settings().optString("pickup")+"\n\n"+SaleSchedule.window(settings()),NativeUi.CARD),16);note("Acércate dentro del intervalo acordado cuando la olla confirme tu reserva.");}
            else{
                add(content,ui.text("Sector de entrega",15,NativeUi.INK,true),18);JSONArray zones=settings().optJSONArray("zones");List<String> labels=new ArrayList<>(),ids=new ArrayList<>(),namesList=new ArrayList<>();labels.add("Elige tu sector");ids.add("");namesList.add("");for(int i=0;zones!=null&&i<zones.length();i++){JSONObject zone=zones.optJSONObject(i);if(!zone.optBoolean("enabled"))continue;double price=SaleRules.deliveryFee(store.subtotal(),zone.optDouble("fee"),settings().optDouble("deliveryFreeFrom",0));labels.add(zone.optString("name")+" · "+(price==0?"Gratis":cash(price)));ids.add(zone.optString("id"));namesList.add(zone.optString("name"));}
                Spinner picker=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels){@Override public View getView(int position,View convert,android.view.ViewGroup parent){TextView view=(TextView)super.getView(position,convert,parent);view.setTypeface(ui.regular);view.setTextColor(NativeUi.INK);view.setTextSize(16);return view;}};picker.setAdapter(adapter);picker.setBackground(ui.background(NativeUi.CARD,NativeUi.LINE,12));picker.setMinimumHeight(dp(54));picker.setContentDescription("Sector de entrega");picker.setSelection(Math.max(0,ids.indexOf(details.optString("zoneId"))));picker.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> parent,View view,int position,long id){put(details,"zoneId",ids.get(position));put(details,"zone",namesList.get(position));updateSummary();}public void onNothingSelected(android.widget.AdapterView<?> parent){}});add(content,picker,6);
                field("address","Dirección de entrega","Sector, manzana, lote, calle o punto acordado",false);field("reference","Referencias para llegar","Casa verde, al pie de las escaleras, frente a la bodega",false);TextView gps=ui.button(locating?"Buscando ubicación…":"Usar mi ubicación actual",false,"pin",()->requestDeliveryLocation());gps.setEnabled(!locating);add(content,gps,16);note("Opcional. Confirma que este sea el lugar donde recibirás la comida el día de venta.");destinationCard(content,details,true);note("Reparto el "+SaleSchedule.day(settings())+". La olla confirmará la hora, el acceso y el punto de encuentro.");
            }
        }else if(step==1){field("customer","Tu nombre","¿A nombre de quién será el pedido?",false);field("phone","Celular de contacto","9 dígitos, empieza con 9",true);add(content,ui.heading("¿Cómo prefieres pagar?",21),22);choices(new String[]{"cash","yape","plin"},new String[]{"Efectivo","Yape","Plin"},details.optString("payment","cash"),key->{captureDetails();put(details,"payment",key);render();});note("Elegir una opción no realiza un cobro. Espera la confirmación de la olla antes de pagar.");}
        else{
            add(content,ui.heading("Así queda tu pedido",22),22);JSONObject cart=state().optJSONObject("cart");java.util.Iterator<String> ids=cart.keys();while(ids.hasNext()){String id=ids.next();JSONObject p=product(id);summaryLine(content,cart.optInt(id)+" × "+p.optString("name"),cash(cart.optInt(id)*p.optDouble("price")),false);}
            LinearLayout contact=ui.message(details.optString("customer"),details.optString("phone"),NativeUi.CARD);add(content,contact,16);String place=details.optString("fulfillment","pickup").equals("delivery")?details.optString("zone")+" · "+details.optString("address")+"\nReferencia: "+details.optString("reference")+(details.optString("meeting").isEmpty()?"":"\n"+details.optString("meeting")):settings().optString("pickup");add(content,ui.message(details.optString("fulfillment","pickup").equals("delivery")?"Delivery el día de venta":"Olla Común Mujeres Emprendedoras",place,NativeUi.CARD),12);if(details.optString("fulfillment","pickup").equals("delivery"))destinationCard(content,details,false);add(content,ui.message("Forma de pago elegida",payment()+" · pago sin realizar",NativeUi.SOFT),12);add(content,ui.message("Fecha de venta",SaleSchedule.day(settings())+(details.optString("fulfillment","pickup").equals("pickup")?"\n"+SaleSchedule.window(settings()):"\nLa olla coordinará la hora del reparto."),NativeUi.GOLD),12);note("Tu reserva quedará guardada en este celular, pendiente de envío a la olla.");
        }
        summary=ui.card();add(content,summary,18);updateSummary();
        if(step<2)primary(step==0?"Continuar con mis datos":"Revisar mi pedido",()->{captureDetails();if(!validStep())return;step++;hideKeyboard();render();});
        else primary("Guardar reserva",()->{captureDetails();try{JSONObject order=store.placePracticeOrder(details);step=0;go("receipt",order.optString("id"));}catch(Exception error){toast(error.getMessage());}});
    }

    private boolean deliveryScreen(){return screen.equals("checkout")&&step==0&&details.optString("fulfillment","pickup").equals("delivery");}
    private void requestDeliveryLocation(){captureDetails();if(!locator.permission()){locator.ask();return;}locating=true;render();locator.start(new DeliveryLocator.Result(){
        public void failed(String message){locating=false;if(!isFinishing()&&!isDestroyed()){toast(message);if(deliveryScreen())render();}}
        public void found(android.location.Location location){locating=false;if(isFinishing()||isDestroyed()||!deliveryScreen())return;captureDetails();try{
            JSONObject candidate=DeliveryDestination.point(location.getLatitude(),location.getLongitude(),location.getAccuracy(),System.currentTimeMillis());render();
            new AlertDialog.Builder(CustomerActivity.this).setTitle("¿Aquí recibirás tu pedido?").setMessage("Entrega: "+SaleSchedule.day(settings())+"\nDirección: "+details.optString("address","Por completar")+"\nPrecisión aproximada: "+Math.round(location.getAccuracy())+" m.\nConfirma solo si este punto corresponde al lugar de entrega.").setNegativeButton("Volver",null).setPositiveButton("Usar este punto",(d,w)->{captureDetails();put(details,"deliveryLocation",candidate);confirmDestination();}).show();
        }catch(Exception error){toast("No pudimos conservar ese punto. Puedes escribir tu dirección.");}}
    });}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==DeliveryLocator.REQUEST){if(locator.permission()&&deliveryScreen())requestDeliveryLocation();else toast("Puedes continuar con tu dirección y referencias.");}}
    private void confirmDestination(){try{DeliveryDestination.confirm(details,settings().optString("saleDate"));store.details(details);render();}catch(Exception error){toast("No pudimos guardar el punto. Vuelve a intentarlo.");}}
    private void destinationCard(LinearLayout parent,JSONObject value,boolean editable){JSONObject point=value.optJSONObject("deliveryLocation");if(point==null)return;boolean valid=DeliveryDestination.validPoint(point);String saleDate=editable||screen.equals("checkout")?settings().optString("saleDate"):value.optString("saleDate");boolean confirmed=valid&&DeliveryDestination.problem(value,saleDate).isEmpty();LinearLayout card=ui.message(confirmed?"Punto de entrega guardado":"Revisa el punto de entrega",valid?"Precisión aproximada: "+Math.round(point.optDouble("accuracy"))+" m. "+(confirmed?"Confirmado para esta dirección y fecha.":"Confirma el punto después de cambiar la dirección o fecha."):"Quita este punto y vuelve a obtener tu ubicación.",NativeUi.CARD);if(valid)add(card,ui.button("Ver punto",false,"pin",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(DeliveryDestination.geo(point))));}catch(Exception error){toast("No hay una app de mapas disponible. La dirección escrita se conserva.");}}),10);if(editable){if(valid&&!confirmed)add(card,ui.button("Confirmar punto para esta entrega",false,null,()->{captureDetails();new AlertDialog.Builder(this).setTitle("¿El punto corresponde a esta dirección?").setMessage(details.optString("address")+"\nVenta: "+SaleSchedule.day(settings())).setNegativeButton("Volver",null).setPositiveButton("Sí, corresponde",(d,w)->confirmDestination()).show();}),10);add(card,ui.button("Quitar ubicación",false,null,()->{captureDetails();details.remove("deliveryLocation");try{store.details(details);render();}catch(Exception error){toast("No pudimos guardar el cambio.");}}),8);}add(parent,card,12);}

    private void hideKeyboard(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);}
    private boolean validStep(){if(step==0&&details.optString("fulfillment","pickup").equals("delivery")){try{store.fee(details);}catch(Exception error){toast(error.getMessage());return false;}if(details.optString("address").length()<4){error("address","Escribe una dirección o punto de encuentro.");return false;}if(details.optString("reference").length()<3){error("reference","Agrega una referencia fácil de reconocer.");return false;}}if(step==0&&details.optString("fulfillment","pickup").equals("delivery")){String problem=DeliveryDestination.problem(details,settings().optString("saleDate"));if(!problem.isEmpty()){toast(problem);render();return false;}}if(step==1){if(details.optString("customer").length()<2){error("customer","Escribe el nombre del pedido.");return false;}if(!SaleRules.validPhone(details.optString("phone"))){error("phone","Escribe 9 dígitos que empiecen con 9.");return false;}}return true;}
    private void summaryLine(LinearLayout parent,String label,String value,boolean strong){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=ui.text(label,strong?19:15,NativeUi.INK,strong);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView amount=ui.text(value,strong?22:15,NativeUi.WINE,true);amount.setGravity(Gravity.RIGHT);row.addView(amount,new LinearLayout.LayoutParams(-2,-2));add(parent,row,10);}
    private void updateSummary(){if(summary==null||!screen.equals("checkout"))return;summary.removeAllViews();add(summary,ui.text("TOTAL DE TU PEDIDO",12,NativeUi.WINE,true),0);summaryLine(summary,"Comida",cash(store.subtotal()),false);try{double fee=store.fee(details);summaryLine(summary,"Entrega",details.optString("fulfillment","pickup").equals("pickup")?"Recojo gratis":fee==0?"Gratis por promoción":cash(fee),false);summaryLine(summary,"Total",cash(store.subtotal()+fee),true);}catch(Exception missing){summaryLine(summary,"Entrega","Elige un sector",false);}}
    private void showOrders(){title("Tus pedidos","Revisa la fecha de venta y cómo recibirás cada reserva.");JSONArray orders=state().optJSONArray("orders");if(orders.length()==0)empty("Todavía no hay pedidos","Elige tu comida y completa los datos para preparar tu pedido.");for(int i=0;i<orders.length();i++){JSONObject o=orders.optJSONObject(i);LinearLayout card=ui.card();add(card,ui.text("PEDIDO N.º "+String.format(Locale.US,"%03d",o.optInt("number")),12,NativeUi.CORAL,true),0);add(card,ui.heading("Pendiente de envío",20),7);add(card,ui.text("Venta: "+SaleSchedule.day(o),15,NativeUi.WINE,true),8);add(card,ui.text(o.optString("customer")+" · "+cash(o.optDouble("total")),16,NativeUi.INK,true),6);add(card,ui.text("Guardado en este celular · pago pendiente",13,NativeUi.MUTED,false),6);add(card,ui.button("Ver mi pedido",false,null,()->go("receipt",o.optString("id"))),12);add(content,card,14);}}
    private JSONObject currentOrder(){JSONArray orders=state().optJSONArray("orders");for(int i=0;i<orders.length();i++)if(orders.optJSONObject(i).optString("id").equals(selectedId))return orders.optJSONObject(i);return null;}
    private void showReceipt(){JSONObject order=currentOrder();if(order==null){go("orders","");return;}add(content,ui.message("Tu reserva quedó guardada","Pendiente de envío a la olla. Se conserva en este celular.",NativeUi.GOLD),0);add(content,ui.heading("Pedido "+String.format(Locale.US,"%03d",order.optInt("number")),25),19);LinearLayout food=ui.card();JSONArray items=order.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);summaryLine(food,item.optInt("quantity")+" × "+item.optString("name"),cash(item.optInt("quantity")*item.optDouble("price")),false);}summaryLine(food,"Entrega",cash(order.optDouble("fee")),false);summaryLine(food,"Total",cash(order.optDouble("total")),true);add(content,food,14);String place=order.optString("fulfillment","pickup").equals("delivery")?order.optString("zone")+" · "+order.optString("address")+"\nReferencia: "+order.optString("reference")+(order.optString("meeting").isEmpty()?"":"\n"+order.optString("meeting")):order.optString("pickup","Olla Común Mujeres Emprendedoras · Manchay");add(content,ui.message("DÍA DE VENTA",SaleSchedule.day(order),NativeUi.GOLD),12);if(!order.optString("fulfillment","pickup").equals("delivery"))add(content,ui.message("PUEDES RECOGER",SaleSchedule.window(order),NativeUi.CARD),12);add(content,ui.message("ENTREGA",place,NativeUi.CARD),12);if(order.optString("fulfillment").equals("delivery"))destinationCard(content,order,false);add(content,ui.message("PAGO SIN REALIZAR","El pago se confirma por separado, después de revisar el dinero recibido.",NativeUi.SOFT),12);primary("Ver mis pedidos",()->go("orders",""));}
}
